import{_ as e,o as d,c as a,ag as r}from"./chunks/framework.DEqXEGcv.js";const u=JSON.parse('{"title":"Error Types","description":"","frontmatter":{},"headers":[],"relativePath":"reference/error-types.md","filePath":"reference/error-types.md"}'),o={name:"reference/error-types.md"};function n(i,t,s,h,c,p){return d(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="error-types" tabindex="-1">Error Types <a class="header-anchor" href="#error-types" aria-label="Permalink to &quot;Error Types&quot;">​</a></h1><p>SMQL uses structured errors with context to help diagnose problems. All errors derive from the <code>SmqlError</code> enum.</p><h2 id="error-variants" tabindex="-1">Error Variants <a class="header-anchor" href="#error-variants" aria-label="Permalink to &quot;Error Variants&quot;">​</a></h2><h3 id="parseerror" tabindex="-1">ParseError <a class="header-anchor" href="#parseerror" aria-label="Permalink to &quot;ParseError&quot;">​</a></h3><p>Returned when the SMQL input cannot be parsed.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>String</td><td>Human-readable error description</td></tr><tr><td><code>span</code></td><td>Option</td><td>Source location (offset, length)</td></tr><tr><td><code>hint</code></td><td>Option</td><td>Suggested fix</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Parse error: Expected &#39;TO&#39; after instance ID</span></span></code></pre></div><p><strong>HTTP Status</strong>: 400 Bad Request</p><h3 id="validationerror" tabindex="-1">ValidationError <a class="header-anchor" href="#validationerror" aria-label="Permalink to &quot;ValidationError&quot;">​</a></h3><p>Returned when data validation fails (constraints, types, schema).</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>String</td><td>What failed</td></tr><tr><td><code>field</code></td><td>Option</td><td>Which field caused the error</td></tr><tr><td><code>hint</code></td><td>Option</td><td>Suggested fix</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Validation error: Field &#39;subject&#39; exceeds MAX(200)</span></span></code></pre></div><p><strong>HTTP Status</strong>: 400 Bad Request</p><h3 id="transitiondenied" tabindex="-1">TransitionDenied <a class="header-anchor" href="#transitiondenied" aria-label="Permalink to &quot;TransitionDenied&quot;">​</a></h3><p>Returned when a transition cannot proceed (guard failure, invalid state change).</p><p>Contains a <code>TransitionDeniedError</code> with:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>instance_id</code></td><td>String</td><td>The instance that was being transitioned</td></tr><tr><td><code>from_state</code></td><td>String</td><td>Current state</td></tr><tr><td><code>to_state</code></td><td>String</td><td>Requested target state</td></tr><tr><td><code>guard_failures</code></td><td>Vec</td><td>List of guard failures with details</td></tr><tr><td><code>hint</code></td><td>Option</td><td>Suggested fix</td></tr></tbody></table><p>Each <code>GuardFailure</code> contains:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>guard_expr</code></td><td>String</td><td>The guard expression that failed</td></tr><tr><td><code>actual_value</code></td><td>Option</td><td>What the expression evaluated to</td></tr><tr><td><code>expected</code></td><td>Option</td><td>What was expected</td></tr><tr><td><code>hint</code></td><td>Option</td><td>Contextual hint</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transition denied: Transition open -&gt; triaged denied for instance 01J5...:</span></span>
<span class="line"><span>  - Guard &#39;assignee IS SET&#39; failed (got: null) — Set the assignee field before triaging</span></span></code></pre></div><p><strong>HTTP Status</strong>: 409 Conflict</p><h3 id="spawnrejected" tabindex="-1">SpawnRejected <a class="header-anchor" href="#spawnrejected" aria-label="Permalink to &quot;SpawnRejected&quot;">​</a></h3><p>Returned when a SPAWN fails validation.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>String</td><td>Why the spawn was rejected</td></tr><tr><td><code>field</code></td><td>Option</td><td>Which field caused the issue</td></tr><tr><td><code>hint</code></td><td>Option</td><td>Suggested fix</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spawn rejected: Required field &#39;customer_id&#39; not provided</span></span></code></pre></div><p><strong>HTTP Status</strong>: 400 Bad Request</p><h3 id="guardfailed" tabindex="-1">GuardFailed <a class="header-anchor" href="#guardfailed" aria-label="Permalink to &quot;GuardFailed&quot;">​</a></h3><p>Returned when a specific guard expression fails.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>String</td><td>Description</td></tr><tr><td><code>guard_expr</code></td><td>String</td><td>The expression</td></tr><tr><td><code>actual_value</code></td><td>Option</td><td>Evaluated result</td></tr><tr><td><code>hint</code></td><td>Option</td><td>Suggested fix</td></tr></tbody></table><h3 id="queryerror" tabindex="-1">QueryError <a class="header-anchor" href="#queryerror" aria-label="Permalink to &quot;QueryError&quot;">​</a></h3><p>Returned when a query cannot be executed.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>String</td><td>Description</td></tr><tr><td><code>hint</code></td><td>Option</td><td>Suggested fix</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Query error: Machine &#39;Unknown&#39; not found</span></span></code></pre></div><p><strong>HTTP Status</strong>: 500 Internal Server Error (or 400/404 depending on cause)</p><h3 id="storageerror" tabindex="-1">StorageError <a class="header-anchor" href="#storageerror" aria-label="Permalink to &quot;StorageError&quot;">​</a></h3><p>Returned when the storage backend encounters an error.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>String</td><td>Description</td></tr><tr><td><code>retryable</code></td><td>bool</td><td>Whether the operation can be retried</td></tr></tbody></table><p><strong>HTTP Status</strong>: 500 Internal Server Error</p><h3 id="notfound" tabindex="-1">NotFound <a class="header-anchor" href="#notfound" aria-label="Permalink to &quot;NotFound&quot;">​</a></h3><p>Returned when a requested entity does not exist.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>entity_type</code></td><td>String</td><td>Type of entity (e.g., &quot;Machine&quot;, &quot;Instance&quot;)</td></tr><tr><td><code>id</code></td><td>String</td><td>The requested ID</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Not found: Instance &#39;01J5...&#39;</span></span></code></pre></div><p><strong>HTTP Status</strong>: 404 Not Found</p><h3 id="conflict" tabindex="-1">Conflict <a class="header-anchor" href="#conflict" aria-label="Permalink to &quot;Conflict&quot;">​</a></h3><p>Returned for optimistic locking failures (version mismatch).</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>String</td><td>Description</td></tr><tr><td><code>hint</code></td><td>Option</td><td>Suggested fix</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Conflict: Version mismatch — expected 3, found 4</span></span></code></pre></div><p><strong>HTTP Status</strong>: 409 Conflict</p><h3 id="timeouterror" tabindex="-1">TimeoutError <a class="header-anchor" href="#timeouterror" aria-label="Permalink to &quot;TimeoutError&quot;">​</a></h3><p>Returned when a timeout operation fails.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>String</td><td>Description</td></tr><tr><td><code>instance_id</code></td><td>Option</td><td>Affected instance</td></tr><tr><td><code>state</code></td><td>Option</td><td>State where the timeout was set</td></tr></tbody></table><h3 id="internal" tabindex="-1">Internal <a class="header-anchor" href="#internal" aria-label="Permalink to &quot;Internal&quot;">​</a></h3><p>Catch-all for unexpected errors.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>String</td><td>Description</td></tr></tbody></table><p><strong>HTTP Status</strong>: 500 Internal Server Error</p><h2 id="http-status-code-mapping" tabindex="-1">HTTP Status Code Mapping <a class="header-anchor" href="#http-status-code-mapping" aria-label="Permalink to &quot;HTTP Status Code Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error Type</th><th>HTTP Status</th></tr></thead><tbody><tr><td>ParseError</td><td>400</td></tr><tr><td>ValidationError</td><td>400</td></tr><tr><td>SpawnRejected</td><td>400</td></tr><tr><td>TransitionDenied</td><td>409</td></tr><tr><td>Conflict</td><td>409</td></tr><tr><td>NotFound</td><td>404</td></tr><tr><td>StorageError</td><td>500</td></tr><tr><td>Internal</td><td>500</td></tr></tbody></table>`,57)])])}const b=e(o,[["render",n]]);export{u as __pageData,b as default};
